import fs from 'node:fs';import fsp from 'node:fs/promises';import path from 'node:path';import assert from 'node:assert/strict';import {captureSnapshot,compareCaptured} from '../runtime/resources/app/lib/snapshots.mjs';import {filePage,fileHash,saveText,renderOffice} from '../runtime/resources/app/lib/file-workspace.mjs';
const root=fs.mkdtempSync(path.resolve('tools/.qa-full-files-')),project=path.join(root,'project'),data=path.join(root,'data');fs.mkdirSync(project);let checks=0;const check=(name,value)=>{assert.ok(value,name);checks++;console.log('PASS',name)};
const file=path.join(project,'large.txt'),text='你好，三体！\n'.repeat(500000);fs.writeFileSync(file,text);let offset=0,assembled='';for(;;){const page=filePage(project,'large.txt',offset,65536);assembled+=page.content;if(page.eof)break;offset=page.nextOffset;}check('large UTF-8 file round trips all pages without character loss',assembled===text);
fs.writeFileSync(path.join(project,'binary.bin'),Buffer.from([0,1,2,255]));check('binary file has navigable hex preview',filePage(project,'binary.bin').hex.includes('ff'));
const before=await captureSnapshot(project,data);check('large text snapshot has complete hash',!!before.files['large.txt'].hash&&!before.incomplete);const version=await fileHash(file);const result=await saveText(project,'large.txt',text+'edited',version,data);check('optimistic text save preserves a backup',!!result.backupVersion&&fs.readFileSync(file,'utf8').endsWith('edited'));
let conflict=false;try{await saveText(project,'large.txt','bad',version,data)}catch(e){conflict=e.code==='FILE_CONFLICT'}check('external modification cannot be overwritten by stale editor',conflict&&fs.readFileSync(file,'utf8').endsWith('edited'));
fs.writeFileSync(path.join(project,'binary.bin'),Buffer.from([0,1,3,255]));const after=await captureSnapshot(project,data);const differences=await compareCaptured(before,after,data,'fixture');check('text and binary changes both retain complete differences',differences.changes.length===2&&differences.changes.every(c=>fs.existsSync(c.patchFile)&&c.beforeHash!==c.afterHash));
const many=path.join(project,'many');fs.mkdirSync(many);for(let n=0;n<20010;n++)fs.writeFileSync(path.join(many,'f'+n),'');const full=await captureSnapshot(project,data);check('snapshot has no 20000-entry cutoff',Object.keys(full.files).length>20000&&!full.incomplete);
for(const ext of ['docx','xlsx','pptx']){const pdf=await renderOffice(path.resolve('tools/.qa-completion-20261101/office'),'sample.'+ext,data);check(ext+' opens through actual native Office PDF pipeline',fs.readFileSync(pdf).subarray(0,4).toString()==='%PDF')}
fs.writeFileSync('tools/full-files-results-20261101.json',JSON.stringify({passed:true,checks,root,type:'actual filesystem, native Git binary/text diff, actual WPS Office conversion; no model calls'},null,2));console.log('CHECKS',checks);
